const body = $json ?? {};

const ev = body.event ?? body.type ?? '';
if (ev !== 'messages.upsert') return [];

const data = body.data ?? {};
const key = data.key ?? {};
if (key.fromMe === true) return [];

const remoteJid = String(key.remoteJid ?? '');
if (!remoteJid || remoteJid.endsWith('@g.us')) return [];

const msg = data.message ?? {};
const text = String(
  msg.conversation ||
    msg.extendedTextMessage?.text ||
    msg.imageMessage?.caption ||
    msg.videoMessage?.caption ||
    msg.documentMessage?.caption ||
    msg.buttonsResponseMessage?.selectedDisplayText ||
    ''
).trim();
if (!text) return [];

const phone = remoteJid.replace('@s.whatsapp.net', '').replace(/\D/g, '');
if (!phone || phone.length < 8) return [];

const providerMessageId = key.id ?? null;
const ts = data.messageTimestamp ?? data.message?.messageTimestamp ?? null;

function instStr(v) {
  if (v == null || v === '') return null;
  if (typeof v === 'object') {
    const x = v.instanceName ?? v.name ?? v.instanceId ?? v.id;
    if (x == null || x === '') return null;
    return String(x).trim();
  }
  return String(v).trim();
}

const candidates = [
  instStr(body.instance),
  instStr(body.instanceName),
  instStr(data.instanceName),
  instStr(data.instanceId),
  typeof body.sender === 'object'
    ? instStr(body.sender?.instance ?? body.sender?.instanceId)
    : null,
  body.session != null ? String(body.session).trim() : null,
].filter(Boolean);

const instanceIdentifier = candidates[0] ?? null;
if (!instanceIdentifier) {
  console.log('[router] descartado: sem instance_name/instance_id derivável');
  return [];
}

const correlationId = $execution?.id ? String($execution.id) : `n8n-${Date.now()}`;

const instanceKey = instanceIdentifier;

return [{
  json: {
    provider: 'evolution',
    provider_message_id: providerMessageId,
    phone,
    text,
    timestamp: ts,
    push_name: data.pushName ?? null,
    instance_key: instanceKey,
    instance_name: candidates.find((c) => c && !/^\d+$/.test(c)) ?? instanceKey,
    instance_id_hint: (/^\d+$/.test(instanceKey)) ? instanceKey : (data.instanceId ? String(data.instanceId) : null),
    instance: instanceKey,
    correlation_id: correlationId,
    raw_event: body
  }
}];

const crypto = require('crypto');

const norm = $input.first().json;

function stop(route, enrichment, apiStatus, parsed) {
  return [{
    json: {
      route,
      api_status: apiStatus ?? null,
      normalized: norm,
      enrichment: enrichment || {},
      core_response: parsed ?? null,
    },
  }];
}

const baseUrlRaw = ($env.API_BASE_URL || '').replace(/\/$/, '');
if (!baseUrlRaw) {
  console.log('[router] API_BASE_URL ausente');
  return stop('config_error', {}, null, null);
}

const url = `${baseUrlRaw}/webhooks/whatsapp/inbound`;

const coreBodyObj = {
  phone: norm.phone,
  name: norm.push_name ?? null,
  message: norm.text,
  external_message_id: norm.provider_message_id ?? null,
};

const bodyJson = JSON.stringify(coreBodyObj);

const hmacSecret = ($env.N8N_HMAC_SECRET || '').trim();
const webhookToken = ($env.N8N_WEBHOOK_TOKEN || '').trim();

let signature = '';
if (hmacSecret.length > 0) {
  signature = 'sha256=' + crypto.createHmac('sha256', hmacSecret).update(bodyJson, 'utf8').digest('hex');
} else if (!webhookToken) {
  console.log('[router] falta credencial — defina N8N_WEBHOOK_TOKEN ou N8N_HMAC_SECRET');
  return stop('config_error', {}, null, null);
}

const headers = {
  'Content-Type': 'application/json',
  'x-webhook-instance': String(norm.instance),
  'x-correlation-id': String(norm.correlation_id),
};
if (signature) headers['x-webhook-signature'] = signature;
else headers['x-webhook-token'] = webhookToken;

let timeoutMs = parseInt(String($env.API_TIMEOUT_MS || '15000'), 10);
if (!Number.isFinite(timeoutMs) || timeoutMs < 1000) timeoutMs = 15000;
if (timeoutMs > 120000) timeoutMs = 120000;

let resp;
const ac = new AbortController();
const tmr = setTimeout(() => ac.abort(), timeoutMs);
try {
  resp = await fetch(url, {
    method: 'POST',
    headers,
    body: bodyJson,
    signal: ac.signal,
  });
} catch (e) {
  clearTimeout(tmr);
  const msg = e && e.message ? String(e.message) : String(e);
  console.log('[router] fetch falhou:', msg);
  console.log('[router] ctx', JSON.stringify({ instance: norm.instance, correlation_id: norm.correlation_id }));
  return stop('error', {}, null, null);
}
clearTimeout(tmr);

let parsed = null;
const rawTxt = await resp.text();
try {
  parsed = rawTxt ? JSON.parse(rawTxt) : null;
} catch (_) {
  parsed = { raw: rawTxt };
}

const logSafe = {
  instance: norm.instance,
  correlation_id: norm.correlation_id,
  status: resp.status,
  code: parsed && parsed.error ? parsed.error : null,
};

if (!resp.ok) {
  console.log('[router] Core HTTP erro |', JSON.stringify(logSafe));
  return stop('error', {}, resp.status, parsed);
}

if (parsed && parsed.duplicate === true) {
  console.log('[router] duplicate |', JSON.stringify(logSafe));
  return stop('duplicate', {}, resp.status, parsed);
}

if (!parsed || parsed.ok !== true) {
  console.log('[router] Core resposta inesperada |', JSON.stringify(logSafe));
  return stop('error', {}, resp.status, parsed);
}

return [{
  json: {
    route: 'agent',
    api_status: resp.status,
    normalized: norm,
    enrichment: {
      tenant_id: parsed.tenantId ?? null,
      customer_id: parsed.customerId ?? null,
      message_id: parsed.messageId ?? null,
      correlation_id: norm.correlation_id,
    },
    core_response: parsed,
  },
}];
